// One-hot incrementing counter, with a simple up-counter to go to 1000.
module TopModule(input clk, input reset, output reg [9:0] q);
  reg [9:0] count;
  always @(posedge clk) begin
    if (reset) begin
      count <= 10'd0;
      q <= 10'd0;
    end else begin
      count <= count + 10'd1;
      if (count == 10'd999) count <= 10'd0;
      q <= count;
    end
  end
endmodule

